'use strict';
(() => {
 const D=window.AUSHANG_DATA;
 const originals=new Map(D.laws.map(x=>[x.id,x]));
 D.laws=(window.AUSHANG_COLLECTION||[]).map((item,index)=>{
  const base=originals.get(item.id)||{};
  const url='https://www.gesetze-im-internet.de/'+item.slug+'/';
  return {icon:'file',color:['green','blue','pink','purple','orange'][index%5],keywords:'',provider:'Gesetze im Internet',url,basisUrl:url,basis:'Ergänzende Gesetzessammlung',scope:'Ergänzende Rechtsinformation. Eine Aufnahme in diese Sammlung bedeutet keine allgemeine eigenständige Aushangpflicht. Die Anwendbarkeit ist anhand der betrieblichen Verhältnisse zu prüfen.',notice:'Der Gesetzestext ist als ergänzende Rechtsinformation enthalten. Konkrete Bekanntmachungs-, Informations- und Zugangspflichten sind anhand der einschlägigen Vorschriften und der betrieblichen Verhältnisse zu bestimmen.',supplement:true,...base,...item,localText:true};
 });
 const BGN='https://www.bgn.de/praevention-arbeitshilfen/praxishilfen-service/vorschriften-und-arbeitssicherheitsinformationen/unfallverhuetungsvorschriften/';
 D.laws.push({...originals.get('dguv1'),group:'BGN · Unfallverhütung',localPdf:'./texts/dguv1.pdf'},
  {id:'dguv2',short:'DGUV V2',title:'Betriebsärztinnen und Betriebsärzte sowie Fachkräfte für Arbeitssicherheit',description:'Betreuung nach der bei der BGN geltenden DGUV Vorschrift 2.',category:'Arbeitsschutz',group:'BGN · Unfallverhütung',icon:'briefcase',color:'blue',provider:'BGN',url:BGN+'DGUV_Vorschrift_2.pdf',basisUrl:BGN+'DGUV_Vorschrift_2.pdf',basis:'DGUV Vorschrift 2 · BGN',scope:'Trägerspezifische BGN-Fassung, gültig ab 1. Januar 2026.',notice:'Der Zugang zu einschlägigen Unfallverhütungsvorschriften richtet sich nach § 12 DGUV Vorschrift 1.',localPdf:'./texts/dguv2.pdf'},
  {id:'dguv3',short:'DGUV V3',title:'Elektrische Anlagen und Betriebsmittel',description:'Unfallverhütungsvorschrift für elektrische Anlagen und Betriebsmittel.',category:'Arbeitsschutz',group:'BGN · Unfallverhütung',icon:'shield',color:'orange',provider:'BGN',url:BGN+'DGUV_Vorschrift_3-1.pdf',basisUrl:BGN+'DGUV_Vorschrift_3-1.pdf',basis:'DGUV Vorschrift 3 · BGN',scope:'Die bei der BGN bereitgestellte Fassung.',notice:'Der Zugang zu einschlägigen Unfallverhütungsvorschriften richtet sich nach § 12 DGUV Vorschrift 1.',localPdf:'./texts/dguv3.pdf'});
 const GROUPS=['Aushang & Bekanntmachung','Weitere Arbeitsgesetze','Arbeitsschutz & Prävention','Branchenspezifische Texte','BGN · Unfallverhütung'];
 D.laws.sort((a,b)=>GROUPS.indexOf(a.group)-GROUPS.indexOf(b.group));
 let readerId=null,readerToken=0,largeText=false;
 const textCache=new Map();

 const $=s=>document.querySelector(s);
 const icons={
 home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',book:'<path d="M12 5v16M3 4c4-1 6 0 9 2 3-2 5-3 9-2v15c-4-1-6 0-9 2-3-2-5-3-9-2z"/>',folder:'<path d="M3 6V4h7l2 3h9v13H3z"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M17 4a3 3 0 0 1 0 6m1 4a5 5 0 0 1 3 5v1"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',settings:'<path d="m9 3-1 3-3 1-2 3 2 2-1 3 3 2 1 3h4l1-3 3-1 3-3-2-2 1-3-3-2-1-3z"/><circle cx="11" cy="11" r="3"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',building:'<path d="M5 21V3h14v18M3 21h18M9 7h1m4 0h1m-6 4h1m4 0h1m-5 10v-5h4v5"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0z"/><circle cx="12" cy="10" r="2.5"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 4 2c-1 .7-1.5 1.2-1.5 2.5M12 17h.01"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',external:'<path d="M14 3h7v7M21 3 10 14M10 3H3v18h18v-7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',balance:'<path d="M12 3v18M6 21h12M4 7h16M6 7l-4 8h8zm12 0-4 8h8zM2 15a4 3 0 0 0 8 0m4 0a4 3 0 0 0 8 0"/>',heart:'<path d="M12 21 3 12C-4 3 9-2 12 7c3-9 16-4 9 5z"/>',sprout:'<path d="M12 21V11M12 14C3 14 3 4 3 4s9 0 9 10zm0-3c0-8 9-9 9-9s1 9-9 9z"/>',file:'<path d="M5 3h9l5 5v13H5zM14 3v5h5M9 12h6m-6 4h6"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12a22 22 0 0 0 18 0m-9 0v4"/>',check:'<path d="m5 12 4 4L20 5"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',print:'<path d="M6 8V3h12v5M6 17H3V8h18v9h-3M6 14h12v7H6z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',plus:'<path d="M12 4v16M4 12h16"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M10 18h4"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="1"/><path d="m3 5 9 8 9-8"/>'
 };
 const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24">${icons[n]||icons.file}</svg>`;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const labels={overview:'Alle Gesetze',library:'Inhaltsverzeichnis',reader:'Gesetz lesen',documents:'Betriebliche Dokumente',contacts:'Ansprechpersonen',favorites:'Meine Favoriten',admin:'Verwaltung'};
 const KEY='aushang-demo-v1';
 let storageOK=true,view='overview',site='osi',category='Alle',query='',installPrompt=null,toastTimer;
 function cleanText(v,max=180){return typeof v==='string'?v.slice(0,max):'';}
 function safeURL(v){try{const u=new URL(v);return u.protocol==='https:'&&!u.username&&!u.password?u.href:'';}catch{return '';}}
 function blankSite(id){return {...D.sites[id],profile:{...D.sites[id].profile},contacts:{...D.sites[id].contacts},favorites:[],documents:[],log:[]};}
 function normalize(raw){const s={osi:blankSite('osi'),example:blankSite('example')};for(const id of Object.keys(s)){const r=raw?.[id];if(!r||typeof r!=='object')continue;s[id].fullName=cleanText(r.fullName,150)||s[id].fullName;s[id].company=cleanText(r.company,70)||s[id].company;s[id].site=cleanText(r.site,70)||s[id].site;for(const key of ['women','youth','tariff']){const allowed=key==='youth'?['unknown','none','one','three']:['unknown','yes','no'];if(allowed.includes(r.profile?.[key]))s[id].profile[key]=r.profile[key];}for(const key of ['complaints','ehs','hr','authority'])s[id].contacts[key]=cleanText(r.contacts?.[key],800);s[id].favorites=Array.isArray(r.favorites)?[...new Set(r.favorites.filter(x=>D.laws.some(l=>l.id===x)))]:[];s[id].documents=Array.isArray(r.documents)?r.documents.slice(0,40).filter(x=>x&&safeURL(x.url)&&cleanText(x.title)).map((x,i)=>({id:`doc${i}`,title:cleanText(x.title),kind:['Tarifvertrag','Betriebsvereinbarung','Sonstiges'].includes(x.kind)?x.kind:'Sonstiges',url:safeURL(x.url)})):[];s[id].log=Array.isArray(r.log)?r.log.slice(0,20).filter(x=>x&&typeof x.message==='string').map(x=>({date:cleanText(x.date,40),message:cleanText(x.message,200)})):[];}return s;}
 let state;try{state=normalize(JSON.parse(localStorage.getItem(KEY)||'{}'));}catch{state=normalize({});storageOK=false;}
 const current=()=>state[site];
 function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{storageOK=false;toast('Speichern nicht möglich. Bitte Browser-Speicher prüfen und Daten exportieren.');return false;}}
 function log(message){current().log.unshift({date:new Date().toISOString(),message});current().log=current().log.slice(0,20);}
 function date(v){const d=new Date(v);return Number.isNaN(d.getTime())?'–':d.toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit',year:'numeric'});}
 function hydrate(){document.querySelectorAll('[data-icon]').forEach(e=>{e.outerHTML=icon(e.dataset.icon)});}
 function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4300);}
 function issues(){const s=current();return [!s.contacts.complaints,!s.contacts.authority,s.profile.women==='unknown',s.profile.youth==='unknown',s.profile.tariff==='unknown'].filter(Boolean).length;}
 function applicability(law){const p=current().profile;if(law.id==='muschg')return p.women==='yes'?'Schwelle laut Demo-Profil erfüllt':p.women==='no'?'Schwelle laut Demo-Profil nicht erfüllt':'Anwendbarkeit prüfen';if(law.id==='jarbschg')return p.youth==='none'?'Keine Jugendlichen laut Demo-Profil':p.youth==='one'?'§ 47 · laut Demo-Profil':p.youth==='three'?'§§ 47–48 · laut Demo-Profil':'Anwendbarkeit prüfen';if(law.id==='tvg')return p.tariff==='yes'?'Verträge am Standort ergänzen':p.tariff==='no'?'Keine Tarifverträge laut Demo-Profil':'Anwendbarkeit prüfen';return law.supplement?'Ergänzende Information':law.category;}
 function row(law){const saved=current().favorites.includes(law.id);return `<article class="law-row"><span class="law-icon ${law.color}">${icon(law.icon)}</span><div class="law-content"><h3 class="law-title">${esc(law.title)}</h3><p class="law-sub">${esc(law.description)}</p><div class="law-meta"><span class="chip">${esc(law.short)}</span><span class="chip ${law.conditional?'conditional':''}">${esc(applicability(law))}</span></div></div><button class="law-open" data-law="${law.id}" aria-label="${esc(law.title)}: Details öffnen"></button><div class="row-actions"><button class="icon-button ${saved?'saved':''}" data-favorite="${law.id}" aria-label="${esc(law.title)} ${saved?'aus Favoriten entfernen':'merken'}" aria-pressed="${saved}">${icon('bookmark')}</button><button class="row-open" data-law="${law.id}" aria-label="${esc(law.title)} öffnen">${icon('arrow')}</button></div></article>`;}
 function intro(eyebrow,title,sub){return `<span class="eyebrow">${eyebrow}</span><h1 class="page-title">${title}</h1><p class="page-sub">${sub}</p>`;}
 function bookCard(law,index){return `<button class="book-card" data-law="${law.id}" aria-label="${esc(law.title)} lesen"><span class="book-spine ${law.color}" aria-hidden="true"></span><span class="book-copy"><span class="book-abbr">${String(index+1).padStart(2,'0')} / ${esc(law.short)}</span><h3>${esc(law.title)}</h3><span class="book-bottom"><span>${law.localPdf?'PDF lesen':'Gesetz lesen'}</span>${law.select?'<span class="book-kind">Auszug</span>':''}${law.conditional?'<span class="book-kind">Bedingt</span>':''}${icon('arrow')}</span></span></button>`;}
 function dashboard(){return `<section class="collection-hero"><div><span class="eyebrow">DIGITALE TEXTSAMMLUNG · ${esc(current().site).toUpperCase()}</span><h1>Aushangpflichtige Gesetze<br><em>& wichtige Vorschriften.</em></h1><p>Das Gesetzesbuch für Ihren Arbeitsalltag. Alle ${D.laws.length} Titel stehen direkt auf dieser Seite – zum Öffnen und Lesen.</p><div class="collection-tools"><button class="button primary" data-scroll="group-0">Zur Gesetzessammlung ${icon('arrow')}</button><button class="button" data-action="install">${icon('phone')}Als App nutzen</button></div></div><div class="edition-cover" aria-hidden="true"><span class="cover-brand">aushang.</span><strong>Gesetze.<br>Direkt<br>zugänglich.</strong><small>TEXTSAMMLUNG · 2026</small></div></section><div class="collection-summary"><span>${icon('book')}<strong>${D.laws.length} Gesetze & Vorschriften</strong></span><span>${icon('shield')}Offizielle Quellen</span><span>${icon('file')}Texte direkt im Portal</span><span>${icon('clock')}Abruf: ${date(D.checked)}</span></div><div class="library-intro-note">Die Sammlung orientiert sich am Umfang gängiger Aushangbücher und enthält auch ergänzende sowie branchenabhängige Vorschriften. Die konkrete Anwendbarkeit und betriebliche Ergänzungen bleiben standortbezogen zu prüfen.</div><div class="collection-layout"><div>${GROUPS.map((g,i)=>{const list=D.laws.filter(l=>l.group===g);return `<section class="collection-group" id="group-${i}"><div class="section-head"><h2><span class="section-number">${String(i+1).padStart(2,'0')}</span>${esc(g)}</h2><span class="section-size">${list.length} Titel</span></div><div class="book-grid">${list.map(l=>bookCard(l,D.laws.indexOf(l))).join('')}</div></section>`;}).join('')}<div class="notice-strip">${icon('info')}<p><strong>Betriebliche Ergänzungen gehören dazu.</strong><br>Konkrete Tarifverträge, Betriebsvereinbarungen, die Beschwerdestelle und ggf. Behördenangaben sind vom Betrieb hinzuzufügen. <button class="button text" data-view="documents">Betriebliche Dokumente ansehen ${icon('arrow')}</button></p></div></div><aside class="collection-aside"><section class="contents-panel"><h2>In diesem Gesetzesbuch</h2>${GROUPS.map((g,i)=>`<a href="#group-${i}" data-scroll="group-${i}"><span>${String(i+1).padStart(2,'0')}</span>${esc(g)}</a>`).join('')}<p>Die Gesetzestexte stammen von Gesetze im Internet; die Unfallverhütungsvorschriften von der BGN.</p></section><section class="side-panel"><h3>Ihr Standort</h3><button class="side-link" data-view="contacts">${icon('users')}Ansprechpersonen${icon('arrow')}</button><button class="side-link" data-view="documents">${icon('folder')}Betriebliche Dokumente${icon('arrow')}</button><button class="side-link" data-action="sources">${icon('shield')}Quellen & Textstand${icon('arrow')}</button><p class="small-text">${issues()} Standortangaben noch offen.<br>Dieser Entwurf ist noch kein betrieblich freigegebener Aushang.</p></section></aside></div>`;}
 function library(favorites=false){if(!favorites)return dashboard();const ls=D.laws.filter(l=>current().favorites.includes(l.id));return intro('PERSÖNLICH GESPEICHERT','Meine Favoriten','Ihre gemerkten Vorschriften auf diesem Gerät und für diesen Standort.')+(ls.length?`<div class="book-grid">${ls.map(l=>bookCard(l,D.laws.indexOf(l))).join('')}</div>`:`<div class="empty">${icon('bookmark')}<h2>Noch keine Favoriten</h2><p>Sie können ein Gesetz beim Lesen mit dem Lesezeichen merken.</p><button class="button" data-view="overview">Zur Gesetzessammlung ${icon('arrow')}</button></div>`);}
 function readerShell(){const l=D.laws.find(x=>x.id===readerId);if(!l)return dashboard();return `<div class="reader-top"><button class="button" data-view="overview">${icon('book')}Zur Gesetzessammlung</button><div style="display:flex;gap:8px"><button class="button" data-action="font">A− / A+</button><button class="button" data-action="print">${icon('print')}Drucken</button><button class="button" data-modal-favorite="${l.id}" aria-pressed="${current().favorites.includes(l.id)}">${icon('bookmark')}${current().favorites.includes(l.id)?'Gemerkt':'Merken'}</button></div></div><div class="reader-heading"><span class="eyebrow">GESETZESSAMMLUNG · ${esc(l.short)}</span><h1>${esc(l.title)}</h1><p>${esc(l.description||'')}</p></div><details class="reader-info"><summary>Bekanntmachung und Anwendbarkeit</summary><p><strong>${esc(l.basis)}</strong><br>${esc(l.scope)}</p><p>${esc(l.notice)}</p><a href="${l.basisUrl}" target="_blank" rel="noopener noreferrer">Rechtsgrundlage beim offiziellen Anbieter</a></details><div id="reader-content" aria-live="polite"><p class="reader-loading">Gesetzestext wird geöffnet …</p></div>`;}
 async function loadReader(){const token=++readerToken;const l=D.laws.find(x=>x.id===readerId);if(!l)return;const pos=D.laws.indexOf(l);const navigation=`<div class="reader-end">${pos>0?`<button class="button" data-law="${D.laws[pos-1].id}">← ${esc(D.laws[pos-1].short)}</button>`:'<span></span>'}${pos<D.laws.length-1?`<button class="button" data-law="${D.laws[pos+1].id}">${esc(D.laws[pos+1].short)} ${icon('arrow')}</button>`:''}</div>`;if(l.localPdf){$('#reader-content').innerHTML=`<div class="reader-source"><strong>Original-PDF der BGN</strong> · Abruf: ${date(D.checked)}<br>Vollständige PDF-Datei, lokal in diesem Entwurf hinterlegt. <a href="${l.url}" target="_blank" rel="noopener noreferrer">Quelle bei der BGN</a></div><a class="button primary" href="${l.localPdf}" target="_blank" rel="noopener noreferrer">PDF in eigenem Fenster öffnen ${icon('external')}</a><p class="legal-note">Wenn Ihr Browser PDFs nicht eingebettet darstellt, nutzen Sie den Link oben.</p><object class="pdf-frame" data="${l.localPdf}" type="application/pdf" aria-label="${esc(l.title)}"><p>Bitte die PDF-Datei über den Link oben öffnen.</p></object>${navigation}`;return;}
 try{let payload=textCache.get(l.id);if(!payload){const r=await fetch(`./texts/${l.id}.json`);if(!r.ok)throw Error(r.status);payload=await r.json();textCache.set(l.id,payload);}if(token!==readerToken||view!=='reader'||readerId!==l.id)return;const source=payload.source;const excerpt=source.excerpt;$('#reader-content').innerHTML=`<div class="reader-source"><strong>${excerpt?'Gesetzesauszug: '+esc(excerpt.join(', ')):'Gesamter Gesetzestext aus der XML-Quelle'}</strong> · Abruf: ${date(source.retrieved)}<br>${esc(source.version.join(' · '))}<br>Quelle: <a href="${source.url}" target="_blank" rel="noopener noreferrer">Gesetze im Internet</a>${source.pdfUrl?` · <a href="${source.pdfUrl}" target="_blank" rel="noopener noreferrer">Original-PDF</a>`:''}${payload.hasGraphics?'<br>Die Quelle enthält Grafiken. Für deren unveränderte Darstellung bitte die Original-PDF öffnen.':''}</div><div class="reader-layout"><article class="law-reader ${largeText?'large':''}" id="law-reader">${payload.sections.map(n=>n.kind==='heading'?`<h2 id="${n.id}">${esc(n.label)}</h2>`:`<section class="norm" id="${n.id}"><h3>${esc(n.label)}</h3><div class="law-text">${n.html}</div>${n.notes?`<div class="law-notes">${n.notes}</div>`:''}</section>`).join('')}</article><aside class="reader-side"><section class="contents-panel"><h2>Im Gesetz blättern</h2><select id="paragraph-picker" aria-label="Zum Paragraphen springen"><option value="">Paragraph auswählen …</option>${payload.sections.filter(n=>n.kind==='norm').map(n=>`<option value="${n.id}">${esc(n.label)}</option>`).join('')}</select><h3>Textdarstellung</h3><p>Der Text wurde aus der offiziellen XML-Fassung für die Bildschirmansicht übernommen. Den Textstand entnehmen Sie der Quellenangabe. Die Original-PDF bewahrt die Gestaltung der Quelle.</p><a class="button" href="${source.pdfUrl||source.url}" target="_blank" rel="noopener noreferrer">Originalfassung ${icon('external')}</a><button class="button" data-view="overview">Alle Gesetze ${icon('book')}</button></section></aside></div>${navigation}`;}catch{if(token===readerToken&&view==='reader')$('#reader-content').innerHTML=`<div class="reader-error"><strong>Der hinterlegte Text konnte nicht geladen werden.</strong><p>Bitte Verbindung prüfen und erneut öffnen. Die offizielle Quelle ist direkt erreichbar.</p><a class="button primary" href="${l.url}" target="_blank" rel="noopener noreferrer">Offizielle Quelle öffnen ${icon('external')}</a></div>`;}}
 function renderResults(){}
 function documents(){const docs=current().documents;return intro('BETRIEBLICHE ERGÄNZUNGEN','Dokumente am Standort','Tarifverträge, Betriebsvereinbarungen und weitere betriebliche Informationen ergänzen die Gesetzesbibliothek.')+`<div class="cards"><article class="doc-card"><span class="law-icon purple">${icon('file')}</span><span class="chip conditional">Am Standort zu ergänzen</span><h2>Tarifverträge & Betriebsvereinbarungen</h2><p>Hier gehören die tatsächlich anwendbaren Vereinbarungen hin. Die Beispielversion enthält keine internen OSI-Dokumente.</p><button class="button" data-law="tvg">Rechtsgrundlage ansehen ${icon('arrow')}</button></article><article class="doc-card"><span class="law-icon pink">${icon('users')}</span><span class="chip conditional">Betriebliche Angabe</span><h2>Beschwerdestelle nach AGG</h2><p>${current().contacts.complaints?esc(current().contacts.complaints):'Die zuständige Stelle, deren Erreichbarkeit und der Beschwerdeweg sind von OSI festzulegen und bekannt zu machen.'}</p><button class="button" data-view="contacts">Ansprechpersonen ansehen ${icon('arrow')}</button></article>${docs.map(d=>`<article class="doc-card"><span class="law-icon blue">${icon('file')}</span><span class="chip">${esc(d.kind)} · lokaler Demo-Link</span><h2>${esc(d.title)}</h2><p>Dieser Link wurde in der lokalen Beispielverwaltung hinterlegt. Er wurde nicht auf rechtliche Gültigkeit oder Berechtigungen geprüft.</p><a class="button" href="${esc(d.url)}" target="_blank" rel="noopener noreferrer">Dokument öffnen ${icon('external')}</a></article>`).join('')}</div><div class="notice-strip">${icon('info')}<p><strong>Flucht- und Rettungspläne vor Ort.</strong><br>Erforderliche Pläne sind nach § 4 Abs. 4 ArbStättV an geeigneten Stellen in der Arbeitsstätte auszulegen oder auszuhängen. Diese Portalansicht ersetzt dies nicht. <a href="https://www.gesetze-im-internet.de/arbst_ttv_2004/__4.html" target="_blank" rel="noopener noreferrer">Rechtsgrundlage öffnen</a></p></div>`;}
 const contactMeta=[['complaints','balance','pink','AGG-Beschwerdestelle','Für Beschwerden wegen Benachteiligung nach § 13 AGG.'],['ehs','shield','green','EHS / Arbeitssicherheit','Für Fragen zu Sicherheit und Gesundheit bei der Arbeit.'],['hr','users','blue','Personalabteilung','Für Fragen zum Arbeitsverhältnis und zu betrieblichen Vereinbarungen.'],['authority','building','purple','Aufsichtsbehörde · Jugendarbeitsschutz','Die zuständige Aufsichtsbehörde und ihre Anschrift sind bei Anwendbarkeit von § 47 JArbSchG bekannt zu geben.']];
 function contacts(){return intro('DIREKTE WEGE','Wer hilft Ihnen weiter?','Die zuständigen Ansprechpersonen und Stellen für Ihren Standort. Angaben werden vom Betrieb festgelegt.')+`<div class="cards">${contactMeta.map(([key,ic,col,title,desc])=>`<article class="contact-card"><span class="law-icon ${col}">${icon(ic)}</span><h2>${title}</h2><p>${desc}</p>${current().contacts[key]?`<p class="contact-placeholder">${esc(current().contacts[key])}</p>`:`<div class="contact-placeholder">Noch nicht hinterlegt · betriebliche Festlegung erforderlich</div>`}</article>`).join('')}</div><p class="legal-note">Die Beispielversion erfindet keine Zuständigkeiten oder Kontaktdaten. Angaben lassen sich unter „Verwaltung“ lokal erproben.</p>`;}
 function option(v,label,selected){return `<option value="${v}" ${selected===v?'selected':''}>${label}</option>`;}
 function admin(){const s=current();return intro('LOKALE BEISPIELVERWALTUNG','Ein Standort. Ihre Angaben.','Probieren Sie aus, wie sich das Informationsportal für Ihren Betrieb einrichten lässt.')+`<div class="admin-banner">${icon('info')}<p><strong>Demo auf diesem Gerät.</strong> Änderungen bleiben in diesem Browser. Es gibt hier keine Anmeldung, zentrale Freigabe oder geschützte Dateiablage. Bitte ausschließlich Beispieldaten verwenden.</p></div>${!storageOK?'<div class="admin-banner">Der Browser-Speicher ist nicht verfügbar. Daten können nach dem Schließen verloren gehen. Bitte exportieren.</div>':''}<form id="profile-form" class="form-panel"><h2>Standortprofil</h2><p>Diese Angaben dienen der Vorbereitung. Sie bestätigen keine betriebliche Rechtsprüfung.</p><div class="form-grid"><label class="field">Unternehmensname<input name="company" required maxlength="70" value="${esc(s.company)}"></label><label class="field">Standort<input name="site" required maxlength="70" value="${esc(s.site)}"></label><label class="field">Regelmäßig mehr als drei Frauen beschäftigt?<select name="women">${option('unknown','Noch zu prüfen',s.profile.women)}${option('yes','Ja',s.profile.women)}${option('no','Nein',s.profile.women)}</select></label><label class="field">Regelmäßig beschäftigte Jugendliche unter 18 Jahren<select name="youth">${option('unknown','Noch zu prüfen',s.profile.youth)}${option('none','Keine',s.profile.youth)}${option('one','Ein bis zwei Jugendliche',s.profile.youth)}${option('three','Mindestens drei Jugendliche',s.profile.youth)}</select></label><label class="field">Anwendbare Tarifverträge vorhanden?<select name="tariff">${option('unknown','Noch zu prüfen',s.profile.tariff)}${option('yes','Ja · konkrete Verträge ergänzen',s.profile.tariff)}${option('no','Nein',s.profile.tariff)}</select></label></div><div class="form-buttons"><button class="button primary" type="submit">${icon('check')}Profil lokal speichern</button></div></form><form id="contacts-form" class="form-panel"><h2>Ansprechpersonen & Stellen</h2><p>Nur Beispieldaten eintragen. Für echte Betriebsdaten ist eine geschützte Bereitstellung einzurichten.</p><div class="form-grid">${contactMeta.map(([key,,,title])=>`<label class="field">${title}<textarea name="${key}" maxlength="800" placeholder="Zuständige Stelle, Erreichbarkeit und ggf. Anschrift">${esc(s.contacts[key])}</textarea></label>`).join('')}</div><div class="form-buttons"><button type="submit" class="button primary">${icon('check')}Angaben lokal speichern</button></div></form><form id="document-form" class="form-panel"><h2>Dokumentenlink ausprobieren</h2><p>Ein Link auf ein bereits bereitgestelltes Beispieldokument. Eine Datei wird hier nicht hochgeladen.</p><div class="form-grid"><label class="field">Dokumenttitel<input name="title" maxlength="180" required placeholder="z. B. Muster-Betriebsvereinbarung"></label><label class="field">Dokumentart<select name="kind"><option>Tarifvertrag</option><option>Betriebsvereinbarung</option><option>Sonstiges</option></select></label><label class="field">HTTPS-Adresse<input name="url" type="url" required placeholder="https://…" maxlength="2000"></label></div><div class="form-buttons"><button type="submit" class="button">${icon('plus')}Link lokal hinzufügen</button></div>${s.documents.length?`<ul class="checklist">${s.documents.map(d=>`<li><span>${esc(d.title)}</span><button class="icon-button" style="margin-left:auto" data-delete-doc="${d.id}" type="button" aria-label="${esc(d.title)} entfernen">${icon('trash')}</button></li>`).join('')}</ul>`:''}</form><section class="form-panel"><h2>Vor Einführung prüfen</h2><p>Arbeitsstand dieses Demo-Profils · kein Compliance-Nachweis</p><ul class="checklist">${[['Beschwerdestelle und Beschwerdeweg festlegen',!!s.contacts.complaints],['Aufsichtsbehörde prüfen und bei Anwendbarkeit ergänzen',!!s.contacts.authority],['Anwendbarkeit des Mutterschutz-Aushangs klären',s.profile.women!=='unknown'],['Anzahl jugendlicher Beschäftigter klären',s.profile.youth!=='unknown'],['Tarifbindung und anwendbare Verträge prüfen',s.profile.tariff!=='unknown']].map(([label,done])=>`<li>${icon(done?'check':'clock')}<span>${label}</span><span class="badge ${done?'done':''}">${done?'Demo-Angabe erfasst':'Offen'}</span></li>`).join('')}<li>${icon('clock')}<span>Zugang für alle Schichten, vollständige Texte und Berechtigungen betrieblich prüfen</span><span class="badge">Vor Einführung</span></li></ul></section><section class="form-panel"><h2>Lokale Daten sichern</h2><p>Export und Import umfassen beide Beispielstandorte, Favoriten und lokale Eingaben.</p><div class="form-buttons"><button class="button" data-action="export">${icon('download')}JSON exportieren</button><button class="button" data-action="import">${icon('folder')}JSON importieren</button><button class="button" data-action="reset">${icon('trash')}Demo zurücksetzen</button><input type="file" id="import-file" accept="application/json,.json" hidden></div></section><section class="form-panel"><h2>Änderungen auf diesem Gerät</h2><p>Lokales, veränderbares Demo-Protokoll. Keine revisionssichere Dokumentation.</p>${s.log.length?s.log.map(e=>`<div class="log-entry"><time>${date(e.date)}</time><p>${esc(e.message)}</p></div>`).join(''):'<p>Noch keine Änderungen vorgenommen.</p>'}</section>`;}
 function render(){const s=current();$('#side-company').textContent=s.company;$('#side-site').textContent=`Standort ${s.site}`;$('#fav-count').textContent=s.favorites.length;$('#crumb-title').textContent=view==='reader'?(D.laws.find(l=>l.id===readerId)?.short||labels.reader):labels[view];$('#law-count').textContent=D.laws.length;$('#site-picker').options[0].textContent=state.osi.site;$('#site-picker').options[1].textContent=state.example.site;$('#site-picker').value=site;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.classList.contains('nav-item')&&b.dataset.view===view));$('#main').innerHTML=`<div class="view-enter">${view==='reader'?readerShell():view==='overview'?dashboard():view==='library'||view==='favorites'?library(view==='favorites'):view==='documents'?documents():view==='contacts'?contacts():admin()}</div>`;if(['library','favorites'].includes(view))renderResults();document.title=`${labels[view]} · aushang. · ${s.site}`;hydrate();if(view==='reader')loadReader();}
 function navigate(next){if(!Object.hasOwn(labels,next))next='overview';view=next;category='Alle';query='';history.replaceState(null,'',`#${view}`);render();$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});$('#menu-toggle').setAttribute('aria-expanded','false');$('.sidebar').classList.remove('open');}
 function showModal(content,eyebrow='INFORMATION'){if($('#dialog').open)$('#dialog').close();$('#dialog-eyebrow').textContent=eyebrow;$('#dialog-content').innerHTML=content;hydrate();$('#dialog').showModal();}
 function lawModal(id){if(!D.laws.some(l=>l.id===id))return;if($('#dialog').open)$('#dialog').close();readerId=id;view='reader';history.replaceState(null,'',`#gesetz/${id}`);render();$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
 function sources(){showModal(`<h2 id="dialog-title" class="dialog-title">Quellen & Hinweise</h2><p class="dialog-desc">Gesetzessammlung mit hinterlegten Texten, gekennzeichneten Auszügen und BGN-PDFs. Quellenabruf: ${date(D.checked)}.</p>${D.laws.map(l=>`<p class="source-item"><a href="${l.basisUrl}" target="_blank" rel="noopener noreferrer">${esc(l.basis)}</a><span>${esc(l.title)} · ${esc(l.provider)}</span></p>`).join('')}<section class="detail-section"><h3>Vor dem betrieblichen Einsatz</h3><p>Diese Beispielversion enthält hinterlegte Gesetzestexte aus offiziellen Quellen, gekennzeichnete Auszüge, BGN-PDFs und lokale Musterfunktionen. Sie bestätigt weder Vollständigkeit noch die Erfüllung sämtlicher Bekanntmachungspflichten. Die konkreten Tarifverträge, Betriebsvereinbarungen, Beschwerdestellen und erforderlichen Behördenangaben sind zu ergänzen.</p><p>Die Bereitstellung ist für alle betroffenen Beschäftigten tatsächlich zugänglich zu gestalten. Für die Einführung sind vollständige Texte, Ausfallsicherheit, Zugänge in allen Schichten und ein geregelter Aktualisierungsprozess zu prüfen. Der Zugriff auf private Smartphones sollte hierfür nicht vorausgesetzt werden.</p><p>Erforderliche Flucht- und Rettungspläne bleiben vor Ort bereitzustellen: <a href="https://www.gesetze-im-internet.de/arbst_ttv_2004/__4.html" target="_blank" rel="noopener noreferrer">§ 4 Abs. 4 ArbStättV</a>.</p><p>OSI Günzburg ist hier ein Beispielprofil. Der Entwurf ist kein offiziell freigegebenes OSI-Portal.</p></section>`);}
 function privacy(){showModal(`<h2 id="dialog-title" class="dialog-title">Datenschutz im Entwurf</h2><p class="dialog-desc">Die Beispielversion hat keine Registrierung, kein Tracking und keine Werbedienste.</p><section class="detail-section"><h3>Lokale Speicherung</h3><p>Favoriten, Standortangaben, Kontakttexte, Dokumentenlinks und das Demo-Protokoll werden im lokalen Speicher dieses Browsers abgelegt. Auf demselben Browser sind sie für andere Nutzende zugänglich. Es gibt keine Synchronisierung zwischen Geräten. Die öffentlichen Gesetzestexte und BGN-PDFs können zusätzlich im Offline-Cache gespeichert werden.</p><h3>Hosting und externe Quellen</h3><p>Beim Aufruf verarbeitet der jeweilige Hosting-Anbieter technische Verbindungsdaten. Beim Öffnen einer externen Rechtsquelle oder eines Dokumentenlinks wird eine Verbindung zum jeweiligen Anbieter hergestellt. Das Portal lädt keine externen Schriftarten oder Analyse-Skripte.</p><h3>Daten löschen</h3><p>„Demo zurücksetzen“ in der Verwaltung entfernt die lokal gespeicherten Eingaben. Die Browserfunktion „Websitedaten löschen“ entfernt zusätzlich den Offline-Cache. Heruntergeladene JSON-Exporte bleiben als Dateien bestehen.</p><h3>Vor Produktiveinsatz</h3><p>Verantwortlicher, Hosting, Zugriffsrechte, Rechtsgrundlagen und die dazugehörigen Datenschutzinformationen sind für die konkrete Bereitstellung festzulegen. Bitte keine personenbezogenen oder vertraulichen Betriebsdaten in diesem Entwurf eintragen.</p></section>`);}
 async function install(){if(installPrompt){await installPrompt.prompt();const result=await installPrompt.userChoice;installPrompt=null;if(result.outcome==='accepted'){toast('Installation gestartet.');return;}}showModal(`<h2 id="dialog-title" class="dialog-title">Auch als App nutzbar.</h2><p class="dialog-desc">Das Portal lässt sich als Web-App auf unterstützten Geräten zum Startbildschirm hinzufügen.</p><div class="install-instructions"><p><strong>Android / Chrome:</strong> Im Browsermenü „App installieren“ oder „Zum Startbildschirm hinzufügen“ wählen.</p><p><strong>iPhone / Safari:</strong> Über „Teilen“ → „Zum Home-Bildschirm“ hinzufügen.</p><p><strong>Computer:</strong> Das Installationssymbol in der Adressleiste oder den entsprechenden Menüpunkt verwenden, sofern verfügbar.</p></div><div class="reference">Die Oberfläche und die hinterlegten Gesetzestexte können nach vollständigem Laden des Offline-Pakets ohne Internet verfügbar sein. Aktuelle externe Quellen und Dokumentenlinks benötigen Internet. Anmeldung und Gerätevorgaben des Hostings können Installation und Offline-Nutzung einschränken. Die tatsächliche Installation ist auf dem Zielgerät zu prüfen.</div>`,'WEB-APP');}
 function favorite(id){if(!D.laws.some(l=>l.id===id))return;const a=current().favorites;const i=a.indexOf(id);i<0?a.push(id):a.splice(i,1);save();render();toast(i<0?'Gesetz in Favoriten gespeichert.':'Gesetz aus Favoriten entfernt.');}
 document.addEventListener('click',e=>{const b=e.target.closest('button,a[data-view],a[data-scroll]');if(!b)return;if(b.dataset.scroll){e.preventDefault();document.getElementById(b.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'});}else if(b.dataset.view){e.preventDefault();navigate(b.dataset.view);}else if(b.dataset.law)lawModal(b.dataset.law);else if(b.dataset.favorite)favorite(b.dataset.favorite);else if(b.dataset.modalFavorite){const id=b.dataset.modalFavorite;favorite(id);lawModal(id);}else if(b.dataset.category){category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(t=>{t.classList.toggle('active',t.dataset.category===category);t.setAttribute('aria-pressed',String(t.dataset.category===category));});renderResults();}else if(b.dataset.deleteDoc){current().documents=current().documents.filter(x=>x.id!==b.dataset.deleteDoc);log('Dokumentenlink lokal entfernt.');save();render();toast('Link entfernt.');}else if(b.dataset.action){const act=b.dataset.action;if(act==='font'){largeText=!largeText;$('#law-reader')?.classList.toggle('large',largeText);}if(act==='print')window.print();if(act==='sources')sources();if(act==='install')install();if(act==='reset-filter'){if(view==='favorites'&&!query&&category==='Alle')navigate('library');else{category='Alle';query='';render();}}if(act==='export'){const payload={format:'aushang-demo-v1',exportedAt:new Date().toISOString(),sites:state};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download='aushang-demo-daten.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Lokale Daten exportiert.');}if(act==='import')$('#import-file').click();if(act==='reset')showModal(`<h2 id="dialog-title" class="dialog-title">Demo zurücksetzen?</h2><p class="dialog-desc">Alle lokalen Eingaben und Favoriten beider Beispielstandorte werden entfernt. Exportieren Sie Ihre Daten vorher, wenn Sie sie behalten möchten.</p><div class="detail-footer"><button class="button primary" data-action="confirm-reset">Lokale Demo-Daten löschen</button><button class="button" data-action="cancel-dialog">Abbrechen</button></div>`);if(act==='cancel-dialog')$('#dialog').close();if(act==='confirm-reset'){state=normalize({});try{localStorage.removeItem(KEY);storageOK=true;}catch{storageOK=false;}site='osi';$('#dialog').close();navigate('overview');toast('Demo auf die Ausgangsdaten zurückgesetzt.');}}});
 $('#dialog-close').addEventListener('click',()=>$('#dialog').close());
 $('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
 $('#menu-toggle').addEventListener('click',()=>{const open=$('.sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));});
 $('#main').addEventListener('click',()=>{if($('.sidebar').classList.contains('open')){$('.sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('.sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
 $('#site-picker').addEventListener('change',e=>{site=e.target.value;category='Alle';query='';render();toast(`Standort gewechselt: ${current().site}`);});
 $('#sources-button').addEventListener('click',sources);$('#privacy-button').addEventListener('click',privacy);$('#help-button').addEventListener('click',install);
 document.addEventListener('input',e=>{if(e.target.id==='search-input'){query=e.target.value;renderResults();}});
 document.addEventListener('change',async e=>{if(e.target.id==='paragraph-picker'&&e.target.value)document.getElementById(e.target.value)?.scrollIntoView({behavior:'smooth',block:'start'});if(e.target.id==='sort-picker')renderResults();if(e.target.id==='import-file'&&e.target.files[0]){const file=e.target.files[0];if(file.size>250000){toast('Datei zu groß. Maximal 250 KB.');return;}try{const parsed=JSON.parse(await file.text());if(parsed.format!=='aushang-demo-v1'||!parsed.sites?.osi||!parsed.sites?.example)throw Error('format');const pending=normalize(parsed.sites);showModal(`<h2 id="dialog-title" class="dialog-title">Demo-Daten importieren?</h2><p class="dialog-desc">Die Eingaben beider Beispielstandorte werden durch den Export ersetzt. Es werden nur bekannte Felder und gültige HTTPS-Dokumentenlinks übernommen.</p><div class="detail-footer"><button class="button primary" id="confirm-import">Import übernehmen</button><button class="button" data-action="cancel-dialog">Abbrechen</button></div>`);$('#confirm-import').onclick=()=>{state=pending;log('Demo-Daten aus JSON importiert.');save();$('#dialog').close();render();toast('Demo-Daten lokal importiert.');};}catch{toast('Ungültige Datei. Bitte einen aushang.-Demo-Export auswählen.');}e.target.value='';}});
 document.addEventListener('submit',e=>{if(!['profile-form','contacts-form','document-form'].includes(e.target.id))return;e.preventDefault();const f=new FormData(e.target);if(e.target.id==='profile-form'){current().company=cleanText(f.get('company'),70).trim()||current().company;current().site=cleanText(f.get('site'),70).trim()||current().site;for(const k of ['women','youth','tariff'])current().profile[k]=f.get(k);log('Standortprofil lokal bearbeitet.');if(save()){render();toast('Standortprofil lokal gespeichert.');}}if(e.target.id==='contacts-form'){for(const k of ['complaints','ehs','hr','authority'])current().contacts[k]=cleanText(f.get(k),800).trim();log('Ansprechpersonen und Stellen lokal bearbeitet.');if(save()){render();toast('Ansprechpersonen lokal gespeichert.');}}if(e.target.id==='document-form'){const url=safeURL(f.get('url'));if(!url){toast('Bitte eine gültige HTTPS-Adresse ohne Zugangsdaten eingeben.');return;}if(current().documents.length>=40){toast('Maximal 40 Demo-Links möglich.');return;}current().documents.push({id:crypto.randomUUID(),title:cleanText(f.get('title')).trim(),kind:f.get('kind'),url});log('Dokumentenlink lokal ergänzt.');if(save()){render();toast('Dokumentenlink lokal hinzugefügt.');}}});
 window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
 function connection(){const c=$('#connection');c.innerHTML=`<span></span>${navigator.onLine?'Online':'Offline · hinterlegte Fassung'}`;c.classList.toggle('offline',!navigator.onLine);}
 window.addEventListener('online',connection);window.addEventListener('offline',connection);window.addEventListener('hashchange',()=>{const hash=location.hash.slice(1);if(hash.startsWith('gesetz/'))lawModal(hash.slice(7));else navigate(hash);});
 const initial=location.hash.slice(1);if(initial.startsWith('gesetz/')&&D.laws.some(l=>l.id===initial.slice(7))){readerId=initial.slice(7);view='reader';}else view=Object.hasOwn(labels,initial)&&initial!=='reader'?initial:'overview';render();connection();
 if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{/* Hosting may restrict offline support. The online portal remains usable. */});
})();
